// src/components/dashboard/Dashboard.js
import React from 'react';
import PortfolioCard from './PortfolioCard';
import TradingPanel from './TradingPanel';
import MarketData from './MarketData';
import { useTheme } from '../../contexts/ThemeContext';

export default function Dashboard() {
  const { isDark } = useTheme();

  return (
    <div className="space-y-6">
      {/* Welcome Section */}
      <div className={`rounded-xl p-6 transition-colors duration-300 ${
        isDark
          ? 'bg-gray-800 border border-gray-700'
          : 'bg-white border border-gray-200'
      }`}>
        <h1 className="text-2xl font-semibold text-gray-900 dark:text-white mb-2">
          Welcome to QuantumTrade
        </h1>
        <p className="text-gray-600 dark:text-gray-400">
          AI-powered trading platform with real-time analytics
        </p>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column */}
        <div className="lg:col-span-2 space-y-6">
          <PortfolioCard />
          <MarketData />
        </div>

        {/* Right Column */}
        <div className="space-y-6">
          <TradingPanel />
          
          {/* Quick Actions */}
          <div className={`rounded-xl p-6 transition-colors duration-300 ${
            isDark
              ? 'bg-gray-800 border border-gray-700'
              : 'bg-white border border-gray-200'
          }`}>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              Quick Actions
            </h3>
            <div className="space-y-3">
              <button className={`w-full py-3 rounded-lg font-medium transition-colors duration-300 ${
                isDark
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}>
                Train AI Model
              </button>
              <button className={`w-full py-3 rounded-lg font-medium transition-colors duration-300 ${
                isDark
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}>
                Run Backtest
              </button>
              <button className={`w-full py-3 rounded-lg font-medium transition-colors duration-300 ${
                isDark
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}>
                Market Analysis
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* AI Insights */}
      <div className={`rounded-xl p-6 transition-colors duration-300 ${
        isDark
          ? 'bg-gray-800 border border-gray-700'
          : 'bg-white border border-gray-200'
      }`}>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          AI Trading Insights
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className={`rounded-lg p-4 border transition-colors duration-300 ${
            isDark
              ? 'bg-gray-700 border-gray-600'
              : 'bg-gray-50 border-gray-200'
          }`}>
            <div className="text-sm font-medium text-gray-600 dark:text-gray-400">SVR Model</div>
            <div className="text-xl font-semibold text-gray-900 dark:text-white">84%</div>
            <div className="text-xs text-gray-500 dark:text-gray-500">Accuracy</div>
          </div>
          <div className={`rounded-lg p-4 border transition-colors duration-300 ${
            isDark
              ? 'bg-gray-700 border-gray-600'
              : 'bg-gray-50 border-gray-200'
          }`}>
            <div className="text-sm font-medium text-gray-600 dark:text-gray-400">GPR Model</div>
            <div className="text-xl font-semibold text-gray-900 dark:text-white">79%</div>
            <div className="text-xs text-gray-500 dark:text-gray-500">Accuracy</div>
          </div>
          <div className={`rounded-lg p-4 border transition-colors duration-300 ${
            isDark
              ? 'bg-gray-700 border-gray-600'
              : 'bg-gray-50 border-gray-200'
          }`}>
            <div className="text-sm font-medium text-gray-600 dark:text-gray-400">Signal Strength</div>
            <div className="text-xl font-semibold text-gray-900 dark:text-white">Strong</div>
            <div className="text-xs text-gray-500 dark:text-gray-500">Bullish Trend</div>
          </div>
        </div>
      </div>
    </div>
  );
}
